import { ref } from 'vue';

// 容器列表
export const containerList = ref([
    { name: 'container-1' },
    { name: 'container-2' },
    { name: 'container-3' },
    { name: 'container-4' }
]);

export const dialogVisible = ref(false);
// 打开弹出框
export const openDialog = () => {
    dialogVisible.value = true;
};
